class Solution {
    public int numberOfSubarrays(int[] nums,int k){
        return atMost(nums,k)-atMost(nums,k-1);
    }
    private int atMost(int[] nums,int limit){
        if(limit<0)return 0;
        int left=0,odd=0,total=0;
        for(int right=0;right<nums.length;right++){
            odd+=nums[right]&1;
            while(odd>limit)odd-=nums[left++]&1;
            total+=right-left+1;
        }
        return total;
    }
}

code.kotlin:
class Solution {
    fun numberOfSubarrays(nums:IntArray,k:Int):Int=atMost(nums,k)-atMost(nums,k-1);
    private fun atMost(nums:IntArray,limit:Int):Int{
        if(limit<0)return 0;
        var left=0;
        var odd=0;
        var total=0;
        for(right in nums.indices){
            odd+=nums[right] and 1;
            while(odd>limit){
                odd-=nums[left] and 1;
                left++
            };
            total+=right-left+1
        };
        return total
    }
}

